import { readFileSync, writeFileSync, chmodSync } from 'node:fs';
import { DatabaseSync } from 'node:sqlite';

// The snapshot is generated by export-demo.py. It excludes active sessions.
const data = JSON.parse(readFileSync('backups/demo-transfer.json', 'utf8'));
const tables = ['users', 'patients', 'payers', 'patient_payers', 'professionals', 'appointments', 'audit', 'encounters', 'encounter_versions', 'quotes', 'sales', 'payments'];
const db = new DatabaseSync(':memory:');
db.exec('PRAGMA foreign_keys=ON');
for (const file of ['drizzle/0000_flippant_fenris.sql', 'drizzle/0001_goofy_sheva_callister.sql']) db.exec(readFileSync(file, 'utf8'));
const literal = value => value === null ? 'NULL' : typeof value === 'number' ? String(value) : "'" + String(value).replaceAll("'", "''") + "'";
const statements = [];
for (const table of tables) {
  const fields = db.prepare(`PRAGMA table_info(${table})`).all().map(row => row.name);
  for (const row of data[table]) {
    if (!fields.every(field => Object.hasOwn(row, field))) throw new Error('Incomplete snapshot');
    statements.push(`INSERT INTO ${table} (${fields.join(',')}) VALUES (${fields.map(field => literal(row[field])).join(',')});`);
  }
}
const sql = statements.join('\n') + '\n';
db.exec(sql);
if (db.prepare('PRAGMA integrity_check').get().integrity_check !== 'ok' || db.prepare('PRAGMA foreign_key_check').all().length) throw new Error('Invalid snapshot');
writeFileSync('backups/cloudflare-demo.sql', sql, { mode: 0o600 });
chmodSync('backups/cloudflare-demo.sql', 0o600);
console.log('Validated snapshot:', Object.fromEntries(tables.map(table => [table, data[table].length])));
db.close();
